<script>
    //import LineChart from './LineChart.js'
    //import axios from "../axios_instance";
    import axios from "../axios_instance";
    import { Form } from "vform";
    import VueApexCharts from 'vue-apexcharts'
    import vClickOutside from 'v-click-outside'
    export default {
        props: {},
        components: {
            'apexchart': VueApexCharts
            // LineChart
            // VueRecaptcha, facebookLogin
        },
        directives: {
        clickOutside: vClickOutside.directive
        },
        data() {
            return {
                monthNames: ["January", "February", "March", "April", "May", "June",
                    "July", "August", "September", "October", "November", "December"],
                monthly_activity: [],
                target_achievement: [],
                year: this.$localStorage.get('year') ? this.$localStorage.get('year') : new Date().getFullYear(),
                newYearAlert : false ,
                achievement: JSON.parse(this.$localStorage.get("achievement")),
                target: JSON.parse(this.$localStorage.get("target")),
                achievement_with_remaining: JSON.parse(this.$localStorage.get("achievement_with_remaining")),
                piecolor: JSON.parse(this.$localStorage.get("piecolor")),
                monthname: JSON.parse(this.$localStorage.get("monthname")),
                //performance_value : JSON.parse(this.$localStorage.get("performance_value")),
                user_data: JSON.parse(this.$localStorage.get("user")),
                base_url: window.base_url,
                api_url: window.api_url,
                search: "",
                item: [],
                route_list: [],
                current_month: '',
                current_monthstr: '',
                month_index: 0,
                deptItems: [],
                WingsItems: [],
                employeeItem: [],                
                filterForm: new Form({
                    dept_id: "",
                    filter_by: "year",
                    wing_id:"",
                    user_id : "",
                }),
                token: this.$localStorage.get("d_token"),
                yearly_achievement: {
                    chartOptions: {
                        colors: JSON.parse(this.$localStorage.get("piecolor")),
                        chart: {
                            height: '100%',
                            type: 'pie',

                        },
                        title: {
                            text: 'Yearly Achievement',
                            align: 'center'
                        },
                        labels: JSON.parse(this.$localStorage.get("monthname")),
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                achievement_1: [12, 34, 12],
                quarter_achievement_1: {
                    chartOptions: {
                        chart: {
                            height: '100%',
                            type: 'pie',

                        },
                        title: {
                            text: 'Quarter-1 Achievement',
                            align: 'center'
                        },
                        labels: ['Jan', 'Feb', 'Mar'],
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                achievement_2: [20, 34, 12],
                quarter_achievement_2: {
                    chartOptions: {
                        chart: {
                            height: '100%',
                            type: 'pie',

                        },
                        title: {
                            text: 'Quarter-2 Achievement',
                            align: 'center'
                        },
                        labels: ['Apr', 'May', 'Jun'],
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                achievement_3: [12, 10, 12],
                quarter_achievement_3: {
                    chartOptions: {
                        chart: {
                            height: '100%',
                            type: 'pie',

                        },
                        title: {
                            text: 'Quarter-3 Achievement',
                            align: 'center'
                        },
                        labels: ['Jul', 'Aug', 'Sep'],
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                achievement_4: [50, 34, 12],
                quarter_achievement_4: {
                    chartOptions: {
                        chart: {
                            height: '100%',
                            type: 'pie',

                        },
                        title: {
                            text: 'Quarter-4 Achievement',
                            align: 'center'
                        },
                        labels: ['Oct', 'Nov', 'Dec'],
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                performance_value: JSON.parse(this.$localStorage.get("performance_value")),
                performance: {
                    chartOptions: {
                        chart: {
                            height: '100%',
                            type: 'donut',
                        },
                        title: {
                            text: 'Performance Management',
                            align: 'center'
                        },
                        labels: ['Performance', 'Remaining '],
                        theme: {
                            monochrome: {
                                enabled: true
                            }
                        },
                        responsive: [{
                            breakpoint: 480,
                            options: {
                                chart: {
                                    width: 200
                                },
                                legend: {
                                    position: 'bottom'
                                }
                            }
                        }]
                    },

                },
                analytics_bar: {
                    series: [{
                        name: 'Target',
                        data: JSON.parse(this.$localStorage.get("target")),
                    },
                    {
                        name: 'Achievement',
                        data: JSON.parse(this.$localStorage.get("achievement"))
                    }

                    ],
                    chartOptions: {
                        chart: {
                            type: 'bar',
                            height: 200
                        },
                        plotOptions: {
                            bar: {
                                horizontal: false,
                                columnWidth: '65%',
                                endingShape: 'rounded'
                            },
                        },
                        dataLabels: {
                            enabled: false
                        },
                        title: {
                            text: 'Yearly Achievement (Monthly)',
                            align: 'center'
                        },
                        stroke: {
                            show: true,
                            width: 2,
                            colors: ['transparent']
                        },
                        xaxis: {
                            categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
                        },
                        yAxes: [{
                            stacked: false,
                            position: "left",
                            id: "y-axis-0",
                            ticks: {
                                beginAtZero: true
                            },
                            scaleLabel: {
                                display: true,
                                labelString: 'Left'
                            },
                        }, {
                            stacked: false,
                            position: "right",
                            id: "y-axis-1",
                            ticks: {
                                min: -1000,
                                max: 8000,
                                stepSize: 1000,
                                beginAtZero: true,
                            },
                            scaleLabel: {
                                display: true,
                                labelString: 'Right'
                            },
                        },],
                        fill: {
                            opacity: 1
                        },
                        tooltip: {
                            y: {
                                formatter: function (val) {
                                    return val
                                }
                            }
                        }
                    },
                },
                dept_analytics_series: [],
                singel_analytics_bar: {
                    series: [{
                        name: 'Target',
                        data: [30, 40, 45, 50, 49, 60, 70, 91, 0, 5, 34, 100]
                    },
                    {
                        name: 'Achievement',
                        data: [14, 30, 30, 40, 30, 0, 50, 21, 0, 5, 24, 55]
                    }],
                    chartOptions: {
                        chart: {
                            type: 'bar',
                            height: 100
                        },
                        plotOptions: {
                            bar: {
                                horizontal: false,
                                columnWidth: '65%',
                                endingShape: 'rounded'
                            },
                        },
                        dataLabels: {
                            enabled: false
                        },
                        title: {
                            text: 'Achievement and Target Analytics ',
                            align: 'center'
                        },
                        stroke: {
                            show: true,
                            width: 2,
                            colors: ['transparent']
                        },
                        xaxis: {
                            categories: ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
                        },
                        yaxis: {
                            title: {
                                text: 'Value'
                            }
                        },
                        fill: {
                            opacity: 1
                        },
                        tooltip: {
                            y: {
                                formatter: function (val) {
                                    return "TK " + val + " M"
                                }
                            }
                        }
                    },
                },                
            };
        },
        mounted: function () {

        },
        created() {
            this.dept_id = this.user_data.dept_id;
            if (this.$route.params.type == 'login') {
                //  alert('ok');
                this.newYearAlert  =  false ; 
                this.$router.push("/home/newyear");
                this.$router.go("/home/newyear");
            }
            if (this.$route.params.type == 'newyear') {
                //  alert('ok');
                this.newYearAlert  =  true ; 
                setTimeout(() => {
                  //  this.NewYear();
                }, 1000);

            } 
            setTimeout(() => {
                // this.NewYearHiden();
            }, 10000);
            this.role_id = this.user_data.role_id;
            if (this.role_id == 5 || this.role_id == 6 || this.role_id == 7) {
                this.filterForm.dept_id = this.user_data.dept_id;
                // this.getWing(); 
                this.getDept();
            } else {
                this.getDept();
            }

            let d = new Date();
            this.month_index = d.getMonth();
            this.current_month = this.monthNames[this.month_index];
            this.current_monthstr = this.current_month.toLowerCase();

            this.getTargetAchievement();
            this.getMonthly_activity();
            this.getWing();
            //GET QUICK LINK LIST
            axios
                .get(this.api_url + "quick-link-list/" + this.user_data.id, {
                    headers: {
                        "Content-Type": "application/json",
                        Authorization: this.token ? `Bearer ${this.token}` : "",
                    },
                })
                .then((response) => {
                    this.route_list = response.data;
                    //console.log('data',response.data);
                });

        },
        methods: { 
            onClickOutside (event) {
               // console.log('Clicked outside. Event: ', event.target.className); 
                if( event.target.className != 'img-fluid newImage'){
                    this.newYearAlert = false ;
                } 
            },
            NewYear(){
                this.newYearAlert = false ;
                //this.$modal.show("new_year");
            },
            NewYearHiden(){
                //console.log('Test');
                this.newYearAlert = false ;
                //this.$modal.hide("new_year");
            },
            changeMonth() {
                let loader = this.$loading.show();
                this.current_month = this.monthNames[this.month_index];
                this.current_monthstr = this.current_month.toLowerCase();
                loader.hide();
            },
            hide_pop() {
                this.$modal.hide("popup-singel");
            },
            filter_data() {
                this.getTargetAchievement();
                this.getMonthly_activity();
            },
            show_pop(row) {

                if (this.item.target && this.item.achievement) {
                    this.item = row;
                    this.$modal.show("popup-singel");
                    // this.dept_analytics_series = [{
                    //             name: 'Target', 
                    //             data: [
                    //               this.item.target.january,
                    //               this.item.target.february, this.item.target.march,
                    //               this.item.target.april, this.item.target.may, 
                    //               this.item.target.june, this.item.target.july, 
                    //               this.item.target.august, this.item.target.september,
                    //               this.item.target.october, this.item.target.november, 
                    //               this.item.target.december]
                    //         },
                    //         {
