            </router-link>
          </li>

          <li itemprop="" class="nav-item" v-if="permission('users')">
            <router-link :to="{ path: '/users' }"><i class="bx bxs-group"></i><span class="menu-item"
                data-i18n="Analytics">Users </span>
            </router-link>
          </li>

          <li itemprop="" class="nav-item">
            <router-link :to="{ path: '/quick_link_settings' }">
              <i class="bx bx-slider-alt"></i><span class="menu-item" data-i18n="Analytics">Quick Link Settings
              </span>
            </router-link>
          </li>
        </ul>
      </div>
    </div>
  </header>
</template>

<script>
import axios from "./axios_instance";

export default {
  props: {},
  components: {},
  data() {
    return {
      token: this.$localStorage.get("d_token"),
      base_url: window.base_url,
      api_url: window.api_url,
      user_data: JSON.parse(this.$localStorage.get("user")),
      role_id: "",
      user: JSON.parse(this.$localStorage.get("user")),
      is_login: false,
      user_type: null,
      notification: "",
      thumbnailphoto: "",
      unread: "",
      p_data: "",
      // defaultImg: 'this.src="' + require(window.base_url+'assets/app-assets/images/logo/logo.png') + '"',
    };
  },

  methods: {
    changeYear() {
      this.$localStorage.set("year", this.year);
      this.$router.go(this.$router.currentRoute);
    },
    refresh() {
      this.$router.go(this.$router.currentRoute);
    },
    Logout() {
      axios
        .get(this.api_url + "auth/logout", {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then((data) => {
          console.log(data);
        });
      this.$localStorage.remove("user");
      this.$localStorage.remove("d_token");
      this.$router.push("/login");
    },
    async getNotification() {
      try {
        await axios
          .get(this.api_url + "get-notification", {
            headers: {
              "Content-Type": "application/json",
              Authorization: this.token ? `Bearer ${this.token}` : "",
            },
          })
          .then(({ data }) => {
            if (data) {
              this.notification = data.notification;
              this.unread = data.unread;

              console.log(this.notification);
            }
            //loader.hide();
          });
      } catch (error) {
        console.log(error);
        //loader.hide();
      }
    },
    notificationRead(notifid) {
      //alert(notifid);
      axios
        .get(this.api_url + "read-notification?nid=" + notifid, {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then((data) => {
          console.log(data);
          this.getNotification();
        });
    },
    profile_thamnail() {
      axios
        .get(this.api_url + "profile_thamnail", {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then((res) => {
          console.log(res);
          console.log("=============================================");
          // console.log('thamnail',window.backend_url);
          this.thumbnailphoto = window.backend_url + res.data.data;
        });
    },
    single_permission() {
      axios
        .get(this.api_url + "single_permission", {
          headers: {
            "Content-Type": "application/json",
            Authorization: this.token ? `Bearer ${this.token}` : "",
          },
        })
        .then((res) => {
          this.p_data = res.data.data[0];
          console.log("ds", this.p_data);
        });
    },
  },
  created() {
    this.profile_thamnail();
    this.role_id = this.user_data.role_id;
    if (this.$localStorage.get("d_token")) {
      this.is_login = true;
      this.user_type = this.user.type;
    } else {
      this.is_login = false;
    }
    this.single_permission();
    this.getNotification();
  },
  computed: {},
};
</script>