<template>
    <div>
        <div class="app-content content"> 
        <div class="content-wrapper">
            <div class="content-header row">
                <div class="content-header-left col-12 mb-1 mt-0">
                    <div class="row breadcrumbs-top">
                        <div class="col-12"> 
                            <div class="breadcrumb-wrapper col-12">
                                <ol class="breadcrumb p-0 mb-0">
                                     <li class="breadcrumb-item"><router-link :to="{ path: '/' }"><i class="bx bx-home-alt"></i></router-link>
                                    </li>
                                    <li class="breadcrumb-item  "> <router-link :to="{ path: '/tour_plan' }"> Tour </router-link>
                                    </li>
                                    <li class="breadcrumb-item active"> New Tour 
                                    </li>
                                    
                                </ol>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            <div class="content-body">  
                <section class="input-validation">
                    <div class="row">
                        <div class="col-md-12">
                            <div class="card">
                                <div class="card-header">
                                    <h4 class="card-title">New Tour</h4>
                                </div>
                                <div class="card-content">
                                    <div class="card-body">
                                        <form @submit.prevent="create()">
                                            <div class="row">
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label>Date</label>
                                                        <div class="controls">
                                                            <datepicker v-model="addForm.date" name="date" class="form-control"  ></datepicker> 
                                                        </div>
                                                    </div> 
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label>Point</label>
                                                        <div class="controls">
                                                            <input type="text" name="point" v-model="addForm.point" :class="{  'is-invalid': addForm.errors.has('point'),  }" class="form-control" data-validation-required-message="This field is required" placeholder="Point">
                                                        </div>
                                                    </div> 
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label>Route</label> 
                                                        <div class="controls">
                                                            <input type="text" name="route_name" v-model="addForm.route_name"   placeholder="Route" :class="{  'is-invalid': addForm.errors.has('route_name'),  }"  class="form-control"  >
                                                        </div>
                                                    </div> 
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label> Common Objective  </label> 
                                                        <div class="controls">
                                                            <input type="text" name="objectives" v-model="addForm.objectives"  :class="{  'is-invalid': addForm.errors.has('route_name'),  }"    class="form-control"  >
                                                        </div>
                                                    </div> 
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label> 
                                                            Special Objective
                                                             </label> 
                                                        <div class="controls">
                                                            <input type="text" name="specia_objective" v-model="addForm.specia_objective"   placeholder="Specia objective"  class="form-control"  >
                                                        </div>
                                                    </div> 
                                                </div>
                                                <div class="col-md-6">
                                                    <div class="form-group">
                                                        <label> 
                                                            Work With
                                                             </label> 
                                                        <div class="controls">
                                                            <input type="text" name="work_with" v-model="addForm.work_with"   placeholder="Work with"  class="form-control"  >
                                                        </div>
                                                    </div> 
                                                </div>
                                              
                                                <div class="col-md-6">
                                                  
                                                    <div class="form-group">
                                                         <label for="Profession">Work Station</label>
                                                         <div class="controls">
                                                            <select  id="Profession" name="work_station" v-model="addForm.work_station" :class="{  'is-invalid': addForm.errors.has('work_station'),  }" class="form-control">
                                                                <option value="Head Quarter">Head Quarter</option>
                                                                <option value="EX Head Quarter">EX Head Quarter</option>
                                                                <option value="Out Station">Out Station</option> 
                                                            </select>
                                                        </div>
                                                    </div> 
                                                </div> 
                                                <div class="col-md-12">
                                                    <div class="form-group">
                                                        <label>   Remarks  </label> 
                                                        <div class="controls">
                                                            <vue-editor name="remarks" v-model="addForm.remarks" :class="{  'is-invalid': addForm.errors.has('remarks'),  }" ></vue-editor> 
                                                        </div>
                                                    </div> 
                                                </div>
                                               
                                            </div>
                                            <button type="submit" class="btn btn-primary">Submit</button>
                                        </form>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </section>
                <!-- Input Validation end -->
            </div>
        </div>
    </div>
    </div> 
</template>
<script>
//import axios from "../../axios_instance"; 
import { Form } from "vform"; 
import Datepicker from 'vuejs-datepicker';
import { VueEditor } from "vue2-editor";
export default {
  props: { 
  },
  components: {
    Datepicker,
    VueEditor
    // VueRecaptcha, facebookLogin
  },
  data() {
    return {
        base_url: window.base_url,
        api_url: window.api_url,  
        token: this.$localStorage.get("d_token"),
        user_data: JSON.parse(this.$localStorage.get("user")),
        addForm: new Form({   
            point : "",
            route_name : "",
            objectives : "",
            specia_objective : "", 
            contactperson : "",
            hq : "",
            work_with : "",
            work_station : "",
            remarks : "",
            feedback : "",
            status : 0,
            approval : 0,
            date : new Date() ,
        }) 
    };
  },
  created() { 
  },
  methods: {
     create(){
     
      try {
         let loader = this.$loading.show();
        //this.addForm.data  =  this.format_Date(this.addForm.data);
        this.addForm.post(this.api_url + "tour_entries", {
            headers: {
              "Content-Type": "application/json", 
              Authorization: this.token ? `Bearer ${this.token}` : ""
            },
          }).then((res) => {
              console.log(res);
              if(res.data.success){
                   this.$toasted.show(res.data.message, {
                    theme: "bubble",
                    duration: 5000,
                    position: "bottom-right",
                    });
              } 
            loader.hide(); 
            this.$router.push('/tour_plan');
        },(error)=>{
          console.log(error);
           loader.hide(); 
        })
      } catch (error) {
         // loader.hide(); 
        console.log(error);
      }
    } 
  },
  computed: {},
};
</script>
